def transform(grid):
    h, w = len(grid), len(grid[0])
    four = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    six = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]
    for r, c in six:
        out[r][c] = 0

    if not four or not six:
        return out

    rmin = min(r for r, c in four)
    rmax = max(r for r, c in four)
    cmin = min(c for r, c in four)
    cmax = max(c for r, c in four)
    six_cmin = min(c for r, c in six)
    six_cmax = max(c for r, c in six)

    # When the objects are side-by-side, reflect toward the 6; otherwise
    # continue the 4-pattern downward.
    if six_cmin > cmax:
        reflected = [(r, 2 * cmax + 1 - c) for r, c in four]
    elif six_cmax < cmin:
        reflected = [(r, 2 * cmin - 1 - c) for r, c in four]
    else:
        reflected = [(2 * rmax + 1 - r, c) for r, c in four]

    for r, c in reflected:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 4
    return out
